const fs = require('fs');
const s = fs.readFileSync(0, 'utf-8').trim();
const stack = [];
const map = { ')': '(', '}': '{', ']': '[' };
let valid = true;
for (const char of s) {
  if (['(', '{', '['].includes(char)) {
    stack.push(char);
  } else if (map[char]) {
    if (stack.pop() !== map[char]) {
      valid = false;
      break;
    }
  }
}
if (stack.length !== 0) valid = false;
console.log(valid ? 'true' : 'false');
